def function_search(xs, x):
    left, right = 0, len(xs)
    while left <= right:
        mid = (left + right) // 2
        mid = int(mid)
        if xs[mid] == x:
            return mid
        elif xs[mid] < x:
            left = mid + 1
        else:
            right = mid - 1
    return -1
```

